    "description": "十多年过去，杰克·萨利已经永久生活在自己的阿凡达躯体中，并与奈蒂莉组建家庭，育有三个孩子，还收养了格蕾丝留下的女儿琪莉。原本平静的生活随着人类势力重返潘多拉而被打破，曾经死去的迈尔斯·夸里奇上校也以新的躯体归来，一心寻找杰克复仇。为了避免族人受到牵连，也为了保护家人，杰克带着奈蒂莉和孩子们离开森林中的家园，前往梅卡伊纳部落寻求庇护。岛礁族首领特诺瓦里与大祭司罗娜尔接纳了他们，萨利一家不得不学习全新的海洋生活方式，并逐渐适应这个以水为家的世界。然而，来自人类的追击并未停止，新的危机也在一步步逼近……",
    "cover": "https://image.tmdb.org/t/p/w500/az6FndKaR11uuxnRQucKJ2mmglg.jpg",
