    "tmdbId": "873",
    "tmdbType": "tv",
    "title": "神探可伦坡",
    "originalTitle": "Columbo",
    "type": "tv",
    "year": "1971",
    "description": "　　《神探可伦坡》《Columbo》是个著名美国经典电视电影系列，由彼得·福克（Peter Falk）主演。自1968年2月20日～2003年1月30日期间，包括2集试播片、本章以及之后陆续推出的特别篇，共69集。本片叙述一名总是穿着一件皱巴巴的棕色风衣，顶着一头乱发，嘴里叼雪茄，开着一辆老爷车的洛杉矶重案组的刑警主角可伦坡（Columbo） 。看似不修边幅的他，总是以敏锐的推理能力侦破各种案件，并让犯人无从抵赖。\n\n　　本片每集独立成篇，一大特点是每集中客串演出犯人角色的全为名演员与名人。另一特点是剧情采用固定的倒叙推理形式：先描述犯人作案的情形，而后描写可伦坡从与嫌疑犯的交谈及证据中确定其嫌疑，逼得犯人不得不自白。犯人原以为天衣无缝的杀人计划，都逃不过他的锐眼。他的一句名言是：‘世上没有完美犯罪’。\n\n　　本片特别之处就是使用较少见的倒叙推理形态，着重如何抓住犯人，而不是常见的查证谁是凶手，犯罪手法或动机。这种剧情铺陈手法，与三谷幸喜编剧的日剧《古畑任三郎》相似。",
    "cover": "https://image.tmdb.org/t/p/w500/2JCD8vab3fircOU8cM2HJCxfv4I.jpg",
    "backdrop": "https://image.tmdb.org/t/p/w1280/d7cH4zt3xoqRQnLqYXMPOrUz5k3.jpg",
