    "description": "“CSI”全称“犯罪现场调查小组”，是一群刑侦专业人士，通过犯罪现场的指纹、毛发、血迹、弹壳、脚印、纤维、碎屑、尸体特征等客观实物，用最先进、高科技的手段进行材料分析，在“一切用证据说话”的基础上合理推理，最终锁定凶手。本片故事发生在纸醉金迷的赌城拉斯维加斯，因此涉及许多赌场风云和内华达州的广袤沙漠。CSI小组成员包括：赌场大佬女儿出身的凯瑟琳·韦罗斯（Marg Helgenberger 饰）、曾经沉迷赌博的黑人华瑞克·布朗（Gary Dourdan 饰）、性格憨厚的尼克·斯托克斯（George Edes 饰）、摇滚青年范儿的DNA鉴识人员葛瑞格·桑德斯（Eric Szmanda 饰）等，在经验老道的吉尔·葛瑞森（William Petersen 饰）带领下，挥拳向赌城所有黑暗。",
