    "description": "20 世纪 70 年代末，两名联邦调查局特工深入调查谋杀凶手心理，与名副其实的杀人狂魔面对面，取得了犯罪科学的新进展。该剧根据1996年前FBI探员约翰·道格拉斯（JohnDouglas）和马克·欧夏克（Mark Olshaker）的著作《心理神探：美国联邦调查局系列犯罪破案揭秘》（MindHunter: Inside the FBI's Elite Serial Crime Unit）改编。",
