    "originalTitle": "功夫",
    "type": "movie",
    "year": "2004",
    "description": "20世纪40年代的上海，街头混混阿星自小受尽欺辱，一心想加入横行上海的黑道势力“斧头帮”，借此出人头地。一次，他假冒斧头帮成员来到贫民社区“猪笼城寨”敲诈居民，却阴差阳错招来了真正的斧头帮。谁也没有想到，这个看似破败的城寨其实卧虎藏龙，除了脾气火爆的包租婆和看似懦弱的包租公，居民中还隐藏着多位身怀绝技的武林高手。原本只想借斧头帮之名谋取好处的阿星，也因此被卷入斧头帮与猪笼城寨之间不断升级的冲突，并开始面对自己究竟要成为怎样的人……",
