    "entityId": "ik001061",
    "slug": "绿巨人浩克",
    "tmdbId": "1927",
    "tmdbType": "movie",
    "title": "绿巨人浩克",
    "originalTitle": "Hulk",
    "type": "movie",
    "year": "2003",
    "description": "　　从小孤苦无依的布鲁斯·班纳长大后成为了美国伯克利军方的科学家，专职从事新型高能炸弹的研究工作，他与罗斯将军的女儿贝蒂·罗斯相恋。事业与感情一帆风顺的布鲁斯似乎已经摆脱了幼年孤独的阴影，走上了一条让人艳羡的成功之路。然而好景不长，在一次试验中，为了保护一名同事，布鲁斯暴露在致命的伽马射线之下，布鲁斯体内的神秘力量被意外唤醒。从此之后，每当情绪激动时，布鲁斯就会失去自我意识，变身成为绿巨人，并且同时具有超强的破坏力和抗拒意志。但布鲁斯并不知道也不想知道自己异于常人的变身能力。对他来说，自己只是一名没有过去、充满困惑的孤独科学家，丝毫不能理解为何会突然招致军方的围捕。面对一系列措手不及的突发事件，布鲁斯的女友贝蒂·罗斯同样感到迷茫无助。她希望帮助布鲁斯，但却遭到负责围捕绿巨人的父亲的阻止。而此时，自称是布鲁斯父亲的神秘人物大卫(尼克·诺尔蒂 饰)出现在罗斯将军身边，他告诫贝蒂不要接近自己的儿子，令贝蒂更感困惑。就在贝蒂思念班纳的同时，罗斯将军所带领的特种军队非但不会同情绿巨人的遭遇，反而早已洒下天罗地网并派出最强大的战士，意欲抓获绿巨人以获知其中的秘密。为了对抗绿巨人的超能力，罗斯将军也有自己的秘密武器，那就是神秘的超能力怪物——“吸收人”(Crusher Creel)。“吸收人”可以变身成为任何自己接触到的物体，与绿巨人势均力敌。而更为惊人的是，“吸收人”其实就是布鲁斯的生身父亲大卫·班纳。由此，布鲁斯的神秘身世开始逐渐清晰起来……",
    "cover": "https://image.tmdb.org/t/p/w500/bxyaXFv6kJbMB3wCRQUHd6e4fGS.jpg",
