    "description": "20世纪30年代，佛山咏春拳师叶问家境优渥，潜心习武，过着平静的生活。1936年，声望卓著的北方武术宗师宫宝森南下佛山举行引退仪式，希望在退出武林之前推动南北武术的交流与传承。叶问被南方武林推举出来，与宫宝森以武会友，也由此结识了他的女儿宫二。不同门派、不同出身的武林人物因为这场南北之会产生交集，而随后席卷而来的战争却彻底改变了他们原本的人生轨迹。在动荡的时代里，叶问、宫二以及一众习武之人不得不面对各自关于传承、尊严与去留的选择……",
