    "type": "tv",
    "year": "1983",
    "description": "南宋年间，全真教道士丘处机与江南七怪武功不相上下，两方决定各培养一个徒弟，日后比武来决定双方武功高低。丘处机的徒弟是金国小王子杨康（苗侨伟 饰），江南七怪的徒弟则是自小随母亲在蒙古生活的郭靖（黄日华 饰）。从蒙古来到中原的郭靖，邂逅了“东邪”黄药师（曾江 饰）的女儿黄蓉（翁美玲 饰）。后又遇见义弟杨康，卷入了杨康一家的纠纷中还有杨康与穆念慈（杨盼盼 饰演）的感情纠葛。在郭靖和黄蓉两人的各种冒险中，两人又结识了“北丐”洪七公（刘丹 饰）、“西毒”欧阳锋（杨泽霖 饰）、“南帝”一灯大师（刘兆铭 饰）、“老顽童”周伯通（秦煌 饰）等武林奇人，经历了丐帮、铁掌帮、争夺武穆遗书等种种事件，两人的爱情也遭遇了许多考验。后郭靖又接到成吉思汗命令，令其率兵攻打南宋。郭靖终逃离蒙古，和冰释前嫌的黄蓉共同保卫襄阳。",
    "cover": "https://image.tmdb.org/t/p/w500/wuOGPke8Dm5g5X4qfYwHu3gXAyX.jpg",
