    "originalTitle": "倚天屠龍記",
    "type": "tv",
    "year": "1986",
    "description": "　　武当派掌门人张三丰 (鲍方) 大寿，七位徒弟正为其祝寿之际，五弟张翠山 (任达华) 被金毛狮王谢逊 (曾江) 要胁至冰火岛上，以追查屠龙刀之秘密。在岛上，山与天鹰教教主之女殷素素 (郑裕玲) 结为夫妇，诞下一子无忌 (梁朝伟) ，并与逊结为义亲。十年后，山一家重返中原，却被武林人士追杀，逼其说出屠龙刀之下落，山为存气节，与素双双自杀。  　　忌长大成人，无意中觅得九阳真经，练成绝世武功。另方面，忌结识了三位红颜知己周芷若 (邓萃雯) 、赵敏 (黎美娴) 和小昭 (邵美琪) ，展开一段段纠缠不清的儿女情仇...其后忌义助明教击退各派，因此获选为教主，然而他淡泊名利，宁愿退隐江湖。",
