    "type": "tv",
    "year": "1984",
    "description": "韦小宝（梁朝伟）为人刁钻聪敏，因义气帮助天地会人打退清兵后，他于稀里胡涂中接受天地会命令进宫“成了”太监。结识少年皇帝康熙（刘德华）时，不识对方身份的韦小宝与之不打不相交结成莫逆之友，并因在得知其身份后协助他铲除奸臣成为宫中红人。韦小宝无意知晓太后是神龙教人所假扮，目的是盗取藏有清朝秘密的四十二章经后，上报康熙，在他的帮助下，康熙救出被囚禁长达十多年的太后，其后韦小宝巧设妙计令顺治与康熙父子团聚，又挑拨神龙教人自相残杀，令康熙对他更加器重，然而他天地会人的身份终没瞒过康熙双眼。此外，周旋于先后爱上的建宁、双儿等七个女人之间，也令韦小宝觉得日子没那么好混。",
