    "description": "　　穷女孩受到命运女神满神（陈红 饰）的特殊眷顾，长大成人后做了集万般宠爱于一身的王妃倾城（张柏芝 饰），但是因此也成了被命运咒语所诅咒的“永远得不到真爱，除非时光倒流，人死复生”之人。在与北宫爵无欢（谢霆峰 饰）、大将军光明（真田广之 饰）等人进行的爱情角力中，倾城一次次被对方当作筹码，咒语灵验。但是身分卑微的奴隶昆仑奴（张东健 饰）却是真心爱着倾城。他期望用自己接近光速的奔跑来打破加诸在倾城身上的命运锁链，好让她返回人生的起点重获选择的权利。",
