    "type": "movie",
    "year": "2015",
    "description": "　　民国时期，外敌入侵，军阀混战，乱世中各类江湖人物纷纷登场。不谙世事的小道士何安下（王宝强 饰），因为闹粮荒离开道观下了山，一脚踏入了光怪陆离的万丈红尘之中，遭遇到一系列诡异奇幻的人物和事件。无心之中，他被卷入太极门掌门之争，并与来华偷师的日本忍者对局。后中统特务欲招揽其做间谍，他却利用这个机会帮京剧武生查老板截杀特务头子报夺妻之恨。何安下周旋于中统、纳粹博士、倭寇和江湖之间，经历一系列匪夷所思的人物和事件。下山时他以一颗赤子之心面对一切，现在发现这个世界与他的想象有多么不同，他终于明白了临下山前师傅说过的一句话：“不择手段非豪杰，不改初衷真英雄”。",
