    "description": "曾经做过音乐人的耿浩如今经营着一家二手唱片店，婚姻破裂后一直无法从感情打击中走出来。眼看好友日渐消沉，在剧组工作的郝义决定借着南下办事的机会，带他踏上一场通往大理的公路旅行，希望用新的邂逅帮他忘掉过去。一路上，两人遇见了形形色色的人，也接连卷入一场场荒唐又狼狈的意外。与此同时，一名同样为感情所困的女子也独自来到大理，试图寻找属于自己的生活方向。两段看似毫不相干的旅程，在欢笑、失落与一次次相遇中，逐渐走向意想不到的交汇……",
