    "year": "2014",
    "description": "成功在美国立足的青年林一（林更新 饰）收到了初恋女友周小栀（周冬雨 饰）寄来的结婚请帖，百感交集的林一准备回国参加，坐飞机的途中他回忆起了自己和周小栀长达十几年的故事。少年林一第一次看到同桌周小栀（张子枫 饰）时就喜欢上了这个文静的小姑娘，但是直到高中毕业两人也没有跟进一步的发展。大学时两人考到了同一所学校，遇到了假冒留学生Tom（隋凯 饰）、文艺青年王尔德（王啸坤 饰）、胖子学霸龚兵（龚格尔 饰）、沉默男李潇（李岷城 饰）、胆小姑娘赵晓溪（赵思园 饰）和美女曹阳（曹阳 饰）等一众好友，随即开始了他们的热血青春……  　　本片取材于高晓松创作的风靡一时的校园歌曲《同桌的你》，高晓松出任了本片的监制。",
