    "description": "1900年的美国旧金山，一名白人女子在唐人街遇害，一名华人男子随即成为主要嫌疑人。案件迅速引发社会震荡，本就处境艰难的当地华人社区也面临越来越强烈的排斥与取缔压力。机缘巧合之下，留美青年秦福与华裔猎人阿鬼因为这桩案件相识，两个性格和行事方式截然不同的人不得不临时组成搭档。为了查清案件真相，也为了替受到牵连的华人争取生存空间，他们穿梭于风云变幻的旧金山，在各方势力之间展开一场笑料与危机并存的探案之旅……",
