    "description": "警校落榜后，天赋异禀却不善言辞的少年秦风被姥姥送到泰国散心，投奔远房表舅唐仁。号称“唐人街第一神探”的唐仁实际上整日靠些小聪明混日子，没想到一次意外之后，他突然成为一桩离奇命案的嫌疑人，而案件背后还牵扯到一批失踪的黄金。为了躲避警方追捕并洗清嫌疑，秦风只得与这个不靠谱的表舅一起展开调查。一个擅长严密推理，一个精通街头生存之道，这对性格迥异的临时搭档就此踏上一场鸡飞狗跳的唐人街探案之旅……",
