    "originalTitle": "今夜不設防",
    "type": "tv",
    "year": "1989",
    "description": "《今夜不设防》是香港亚洲电视制作的经典倾谈节目，由香港亚洲电视制作，由香港三大才子黄沾、倪匡、蔡澜主持，监制为赵汝强。亚洲电视于1989年至1990年间制作的成人清谈节目，由黄沾、倪匡及蔡澜主持，于星期六晚上深夜时段播出。每集皆会邀请不同嘉宾接受访问，由女艺人以至演员及歌手等，节目内容在当时的香港社会而言较为大胆，主持人曾在节目中讨论性与爱相关话题，但并无发出违反香港法例的言论；3位主持人亦不时在节目内吸烟、饮酒及讲粗口。在节目启播初期，每当3位主持人讲粗口时，电视台会以音频信号「哔」一声以盖过原有的粗口，但由于观众觉得「哔」的信号太过碍耳，经反映后电视台取消了「哔」信号声并直接播出3位主持原有的粗口。今夜不设防共制作两辑共26集，先录像经剪接播出，每周播放一集，曾创下甚高的收视率。英国广播公司的外景队曾经拍摄节目录像的情况。节目亦曾制作一集《金装今夜不设防》，于一个私家游泳池进行录像。",
    "cover": "https://image.tmdb.org/t/p/w500/h2uyanrviSRjgmBKEaEBTbIANAM.jpg",
