    "originalTitle": "Late Show with David Letterman",
    "type": "tv",
    "year": "1993",
    "description": "《大卫·莱特曼深夜秀》（Late Show with David Letterman）是美国CBS电视台的一档夜间脱口秀节目，由大卫·莱特曼主持。该节目于1993年8月30日首次播出，由莱特曼的制作公司Worldwide Pants Incorporated和CBS电视制作工作室联合制作。节目中的音乐总监及现场乐队——CBS交响乐团的领队是保罗·沙佛。首席编剧为马特·罗伯茨，播音员为艾伦·卡尔特。在美国各大主流深夜节目中，《大卫·莱特曼深夜秀》在累积平均观众数方面排名第二，播出集数方面位列第三。2009年，该节目的广告收入高达2.71亿美元，在同类节目中居首。\n\n在美国大多数市场，《大卫·莱特曼深夜秀》通常于东部/太平洋时间晚上11点35分播出，但录制时间为周一至周三下午4点30分，周四则分别在下午3点30分和6点进行两次录制。通常情况下，周四录的第二期节目会在当周周五播出。\n\n2002年，《大卫·莱特曼深夜秀》被《电视指南》（TV Guide）评为“有史以来最伟大的50个电视节目”中的第七名。根据与Worldwide Pants签订的合同，CBS已将该节目的播出合约延续至2014年；届时，大卫·莱特曼将超越约翰尼·卡森，成为任职时间最长的深夜脱口秀主持人。",
