    "description": "《Running Man》（韩语：런닝맨）是由韩国SBS电视台在《星期天真好》单元推出的户外竞技真人秀节目。\n\n节目致力于打造一个不同于Real variety的新型态娱乐节目。每期有不同的主题，由不同的嘉宾参演，分为不同的队伍进行比赛，通过完成各种游戏任务，最后获胜一方将获得称号或奖品。\n\n包括七名固定成员是刘在石、池石镇、金钟国、HAHA（河东勋）、宋智孝，以及2017年加入的全昭旻、梁世灿。前成员宋仲基、Lizzy（朴秀英）、Gary（姜熙建）、李光洙因个人发展原因离开。2023年10月30日，成员全昭旻将录制完最后一期《Running Man》后正式离开；12月18日，经纪公司表示，池石镇因身体原因暂时退出《Running Man》。",
