    "type": "tv",
    "year": "2012",
    "description": "本故事讲述了20世纪80年代改革开放初期，在温州创业潮兴起之时，温州瑞安古树村的周万顺毅然决定将年仅13岁的女儿周阿雨只身送往意大利。自己则把祖屋和全部家当卖掉，带着妻子赵银花和儿子周麦狗背井离乡徒步来到温州。到温州后进 城的周万顺从拾荒做起，一步一步变身为成功商人。爱面子又叛逆的周麦狗为了摆脱父亲，羞愤之中离家出走大西北，开始了自己的艰辛创业路。而远在意大利的周阿雨排除万难从洗碗工做起，凭借出色的商业头脑在意大利普拉托成功创业。周万顺和他的家人在时代的商业大潮中又将经历怎样的沉浮故事呢？",
