    "description": "1937年，日本帝国主义发动全面侵华战争。淞沪会战末期，中日双方激战已持续近三个月，上海局势危急。国民革命军第88师第262旅第524团团副谢晋元奉命率部坚守苏州河畔的四行仓库，掩护主力部队撤退。由于苏州河对岸就是公共租界，租界内的中外人士也亲眼见证了这场惨烈的保卫战。为壮声势，守军对外号称“八百壮士”。在接下来的四天里，羊拐、端午、老铁、老算盘等人在生死考验中展现出各自不同的人性，也共同见证了一段悲壮的历史……",
