    "description": "《毛雪汪》是一档以原生朋友关系为切入点的场景化真人秀综艺节目。节目以友情为纽带，以“毛雪汪之家”为主要拍摄场景，讲述每周在这里相聚的毛不易、李雪琴和他们朋友之间真实有趣的故事，在嬉笑中撕开生活日常的现状，展现当下年轻人丰富的青春生活和精神世界，记录真实的成长。节目常年周更播出，为城市中努力打拼的年轻人带来陪伴和情绪上的健康疗愈。",
