    "originalTitle": "回家的诱惑",
    "type": "tv",
    "year": "2011",
    "description": "在周围人的眼中，林品如与洪世贤是一对让人羡慕的模范夫妻，二人郎才女貌，天作之合，但是家家都有一本难念的经。随着时光的流逝，婚姻之初的浪漫情怀渐渐转淡，取而代之的是生活中的各种现实问题。林品如因始终未能怀孕而遭到婆婆指责，日常生活里充满了磕磕绊绊。与此同时，林品如留学法国的闺蜜艾莉突然带着小男孩洪尚恩回国，而洪尚恩竟然是洪世贤的亲生骨肉。艾莉为了挽回失去的恋情，不惜向好友宣战。林品如得知后，伤心欲绝的同时发现自己也怀孕了。洪世贤带着歉意和林品如坦白时，林品如不慎失足落海，所幸被高文彦救起，痛彻心扉的她决定抛弃过去，重新振作并努力学习，巧合下化名高珊珊，改头换面变成了一个新时代女性。",
