    "year": "2014",
    "description": "本剧讲述1937年南京大屠杀的四十九日里发生的故事。日本军队进入沦陷的南京城，奉命掩埋中国死难士兵和战俘尸体。与此同时，市中心的圣马德伦教堂中迎来了一群不速之客，十来个女学生和秦淮河女子，她们殊途同归只为同一件事――逃难。紧接着许多男人也因为各种原因进入了教堂。围墙外的日军寻找各种借口进入教堂，圣马德伦教堂的后院成为他们填埋尸体掩盖罪证的目标，国际安全区的组织者尝试各种解救教堂被困人员的方案，却屡屡失败。教堂中的男人们为了保护藏在教堂阁楼和地窖中的女人，献出了自己的生命，女人们或者选择了有尊严地死去，或者进行了最壮烈的抵抗。在这四十九个日夜里，他们和她们，在一次次地求生、抵抗、毁灭和复活中缔结了爱情、亲情和友情，曾懦弱地变成了勇士、曾迷失的找到了方向、曾虚无的得到了收获、曾有罪的完成了救赎。",
    "cover": "https://image.tmdb.org/t/p/w500/ulZfJlnPxAf308gGHXWrp5xcstz.jpg",
