    "description": "大型礼仪公德脱口秀\n\n用各种形式来传播中国千年礼仪之邦的礼仪文化，让国民在娱乐嬉笑之余感受中华传统美德的精髓并借此发扬光大是节目定位的深度体现，也是节目创建的一种背景，随着节目题材范围的拓宽，节目的核心气质是青春励志，并将把“青春励志”和“传统礼仪”作为必守的原则。",
