    "type": "tv",
    "year": "2016",
    "description": "节目中每期有多位明星嘉宾出席，扮演不同的人物角色，他们中有一个侦探、一个凶手和四个嫌疑人，并同处于一个固定空间。他们共同面对一起精心策划的谋杀案，并需要通过搜集证据和推理找出真正的凶手。根据节目设定，整个过程中只有凶手一人可以说谎，为了隐藏身份会选择嫁祸他人，洗脱自己的嫌疑。\n\n《明星大侦探》是芒果TV小盒子工作室推出的系列明星推理真人秀节目。以“烧脑的剧情”与“悬疑推理以及找出真相完成破案”等节目主打，结合电视剧与综艺节目特点激发明星们的智慧的脑与刺激的剧情。等侦探们来破案，完成推理。节目制作模式引进自韩国JTBC节目《Crime Scene 犯罪现场》并进行本土化，芒果TV购得独家版权，并在原版PD指导下历时7个月制作了第一季节目。\n\n第7季起由晏吉工作室制作，并节目改名《大侦探》，转型为普法教育推理节目，并与最高人民法院共同推出全民普法宣传教育环节《大侦探合议庭》。",
