    "description": "许红豆因为闺蜜去世，生活和工作陷入低谷，她独自前往大理云苗村的“有风小院”休息调整。在那里，她认识了辞去高薪工作回乡创业的当地人谢之遥，还有一群从大城市过去的同龄人。在日常相处中，谢之遥感受到了许红豆的善良和认真，便邀请许红豆用她多年的酒店从业经验，帮助当地提升员工服务意识，为发展云苗村的文化旅游事业助力。同时，许红豆也被谢之遥想要建设家乡，让乡亲们可以壮有所用老有所依的理想打动，两人互生情愫，最终走到了一起。在大理，许红豆和小院里的其他人被当地村民的勤劳与韧性和他们苦辣酸甜的人生感动了，她们重新审视过往，互相帮助、互相启示，在有风的地方整理好心情，获得力量重新出发。",
    "cover": "https://image.tmdb.org/t/p/w500/qaYfoLzWtOLaVoNvOeNBZYIjo1V.jpg",
