    "description": "明朝建文四年，朱棣率兵攻下帝都应天，御史大夫景清夫妻罹难，长女若微被副将孙愚所救，次女蔓茵为太子朱高炽所救。骨肉同胞，一在宫中，一在江湖，同时长大。十年之后，若微随一批靖难遗孤入城刺杀朱棣，刺杀失败，若微遭遇皇太孙朱瞻基，两个年轻人是敌是友，自有一份因缘。造化弄人，若微 与妹妹蔓茵同时嫁入宫中，目睹了国家正在从乱象中恢复，平关外，迁首都，通运河，郑和下西洋，扬威海外，编撰《永乐大典》，盛世将成。若微决心放弃执念，辅佐登上皇位的丈夫朱瞻基，在丈夫死前发誓要替他守护好江山。她历经了北京保卫战等，重用于谦，救大明王朝于危难，在中国历史上写下了辉煌壮丽的一页。",
